const PALETTES = {
  terracotta: ['#ede4d4','#d8c4a0','#caa479','#b8754f','#974a3a','#642822'],
  sage:       ['#e8e7d6','#c9d2b3','#9eb288','#728c64','#4f6948','#2e4530'],
  slate:      ['#e6ebef','#bdcad4','#8ea1b1','#5e7689','#3d556a','#22344a'],
  rose:       ['#ece1de','#dbb9b9','#c08e95','#9a5e72','#6d3f56','#412236'],
  teal:       ['#dde7e5','#a8c2bf','#6fa097','#487a72','#2e5953','#1a3833'],
  lavender:   ['#e7e1ec','#c5b4d3','#a08abb','#7e639d','#5a417a','#3a2855'],
};
// Diverging uses the chosen palette on both sides — light slate/sage/rose/etc
// indicates "less crowded than typical", dark indicates "more crowded than typical".
// Direction is still readable from the bar going left or right of the 0 axis.
const NEUTRAL = '#ece5d6';

const hexToRgb = (h) => [parseInt(h.slice(1,3),16), parseInt(h.slice(3,5),16), parseInt(h.slice(5,7),16)];
const lerpChan = (a, b, t) => Math.round(a + (b - a) * t);
const blend = (a, b, t) => {
  const ca = hexToRgb(a); const cb = hexToRgb(b);
  return '#' + [0,1,2].map(k => lerpChan(ca[k], cb[k], t).toString(16).padStart(2, '0')).join('');
};
const labelFg = (bg) => {
  const [r,g,b] = hexToRgb(bg);
  return (0.299*r + 0.587*g + 0.114*b) > 150 ? '#1a1a1a' : '#fafafa';
};
const len = (v) => (typeof v.length === 'number' ? v.length : (v.toArray ? v.toArray().length : 0));
const at  = (v, i) => (typeof v.get === 'function' ? v.get(i) : v[i]);

const series = context.panel.data.series && context.panel.data.series[0];
if (!series || !series.fields) return {};
const f = (n) => { const x = series.fields.find(x => x.name === n); return x ? x.values : null; };
const venueF = f('venue');
const diffF  = f('difference_from_median');
const countF = f('current_count');
const medianF= f('historical_median_current_count');
const ratioF = f('current_crowding_ratio');
const sampF  = f('sample_count');
const fetchF = f('latest_fetched_at');
if (!venueF || !diffF || len(venueF) === 0) return {};

const paletteName = context.grafana.replaceVariables('${palette}');
const stops = PALETTES[paletteName] || PALETTES.slate;

// stops layout: [light0, light1, mid-light, mid-dark, dark0, dark1]
const diverging = (diff) => {
  if (diff <= -10) return stops[2];
  if (diff <= -3)  return blend(stops[2], stops[1], (diff + 10) / 7);
  if (diff <= 0)   return blend(stops[1], NEUTRAL,  (diff + 3) / 3);
  if (diff <= 3)   return blend(NEUTRAL,  stops[3], diff / 3);
  if (diff <= 10)  return blend(stops[3], stops[5], (diff - 3) / 7);
  return stops[5];
};

const yLabels = [];
const barData = [];
const info = [];
for (let i = 0; i < len(venueF); i++) {
  const venue = at(venueF, i);
  const count = at(countF, i);
  const median = at(medianF, i);
  const diff = at(diffF, i);
  const ratio = at(ratioF, i);
  const samples = at(sampF, i);
  const fetched = at(fetchF, i);
  yLabels.push(venue + '\n' + count + '/' + Number(median).toFixed(0) + ' · ' + Math.round(ratio * 100) + '%');
  const color = diverging(diff);
  barData.push({
    value: diff,
    itemStyle: { color },
    label: { color: labelFg(color) },
  });
  info.push({ venue, count, median, diff, ratio, samples, fetched });
}

return {
  grid: { left: 10, right: 80, top: 20, bottom: 30, containLabel: true },
  xAxis: {
    type: 'value',
    axisLabel: { color: '#888', fontSize: 10 },
    splitLine: { lineStyle: { color: '#2a2a2a' } },
  },
  yAxis: {
    type: 'category',
    data: yLabels,
    axisLabel: { color: '#ccc', fontSize: 11, lineHeight: 15, align: 'right', margin: 14 },
    axisTick: { show: false },
    axisLine: { show: false },
  },
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      const t = info[p.dataIndex];
      return '<b>' + t.venue + '</b><br/>' +
             'current: ' + t.count + '<br/>' +
             'historical median: ' + Number(t.median).toFixed(1) + '<br/>' +
             'diff: ' + (t.diff > 0 ? '+' : '') + Number(t.diff).toFixed(2) + '<br/>' +
             'crowding: ' + (t.ratio * 100).toFixed(1) + '%<br/>' +
             'samples: ' + t.samples + ' weeks';
    },
  },
  series: [{
    type: 'bar',
    data: barData,
    barWidth: 28,
    label: {
      show: true,
      position: 'inside',
      formatter: (p) => (p.value > 0 ? '+' : '') + Number(p.value).toFixed(2),
      fontSize: 12,
    },
  }],
};

const PALETTES = {  terracotta: ['#ede4d4','#d8c4a0','#caa479','#b8754f','#974a3a','#642822'],
  sage:       ['#e8e7d6','#c9d2b3','#9eb288','#728c64','#4f6948','#2e4530'],
  slate:      ['#e6ebef','#bdcad4','#8ea1b1','#5e7689','#3d556a','#22344a'],
  rose:       ['#ece1de','#dbb9b9','#c08e95','#9a5e72','#6d3f56','#412236'],
  teal:       ['#dde7e5','#a8c2bf','#6fa097','#487a72','#2e5953','#1a3833'],
  lavender:   ['#e7e1ec','#c5b4d3','#a08abb','#7e639d','#5a417a','#3a2855'],
};

const series = context.panel.data.series && context.panel.data.series[0];
if (!series || !series.fields) return {};
const hexToRgb = (h) => [parseInt(h.slice(1,3),16), parseInt(h.slice(3,5),16), parseInt(h.slice(5,7),16)];
const lerpChan = (a, b, t) => Math.round(a + (b - a) * t);
const interpStops = (r) => {
  if (r <= 0) return stops[0];
  if (r >= 100) return stops[5];
  const idx = r / 20;
  const i0 = Math.floor(idx);
  const i1 = Math.min(5, i0 + 1);
  const t = idx - i0;
  const c0 = hexToRgb(stops[i0]);
  const c1 = hexToRgb(stops[i1]);
  return '#' + [0,1,2].map(k => lerpChan(c0[k], c1[k], t).toString(16).padStart(2, '0')).join('');
};
const labelFg = (r) => {
  const [rr, gg, bb] = hexToRgb(interpStops(r));
  return (0.299 * rr + 0.587 * gg + 0.114 * bb) > 150 ? '#1a1a1a' : '#fafafa';
};
const len = (v) => (typeof v.length === 'number' ? v.length : (v.toArray ? v.toArray().length : 0));
const at  = (v, i) => (typeof v.get === 'function' ? v.get(i) : v[i]);

const field = (n) => { const f = series.fields.find(x => x.name === n); return f ? f.values : null; };
const wd     = field('weekday_number');
const slot   = field('slot_label');
const cnt    = field('avg_count');
const ratio  = field('crowding_ratio');
const samp   = field('sample_count');
if (!wd || !slot || !cnt || !ratio || !samp || len(wd) === 0) return {};

const paletteName = context.grafana.replaceVariables('${palette}');
const stops = PALETTES[paletteName] || PALETTES.slate;
const metric = context.grafana.replaceVariables('${metric}');

const DAYS = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];

const seen = new Set();
const yCats = [];
for (let i = 0; i < len(slot); i++) {
  const s = at(slot, i);
  if (!seen.has(s)) { seen.add(s); yCats.push(s); }
}

const heatData = [];
for (let i = 0; i < len(wd); i++) {
  const x = at(wd, i) - 1;
  const y = yCats.indexOf(at(slot, i));
  const c = Math.round(at(cnt, i));
  const r = Math.round(at(ratio, i) * 100);
  const s = at(samp, i);
  heatData.push({ value: [x, y, r, c, r + '%', s], label: { color: labelFg(r) } });
}

const labelIdx = metric === 'crowding_ratio' ? 4 : 3;


return {
  grid:    { left: 60, right: 30, top: 40, bottom: 60, containLabel: true },
  xAxis:   { type: 'category', data: DAYS, position: 'top', axisLabel: { color: '#aaa' }, splitArea: { show: false } },
  yAxis:   { type: 'category', data: yCats, inverse: true, axisLabel: { color: '#aaa', fontSize: 10 } },
  visualMap: {
    type: 'continuous', dimension: 2,
    min: 0, max: 100, calculable: true,
    orient: 'horizontal', left: 'center', bottom: 5,
    inRange: { color: stops },
    text: ['100%', '0%'],
    textStyle: { color: '#aaa' },
  },
  tooltip: {
    formatter: (p) => {
      const [x, y, r, c, _rp, s] = p.value;
      return DAYS[x] + ' ' + yCats[y] + '<br/>' +
             'avg_count: ' + c + ' 人<br/>' +
             'crowding_ratio: ' + r + '%<br/>' +
             'sample_count: ' + s + ' 週';
    },
  },
  series: [{
    type: 'heatmap',
    data: heatData,
    label: {
      show: true,
      formatter: (p) => String(p.value[labelIdx]),
      fontSize: 10,
    },
    emphasis: { itemStyle: { borderColor: '#fff', borderWidth: 1 } },
  }],
};

const PALETTES = {
  terracotta: ['#ede4d4','#d8c4a0','#caa479','#b8754f','#974a3a','#642822'],
  sage:       ['#e8e7d6','#c9d2b3','#9eb288','#728c64','#4f6948','#2e4530'],
  slate:      ['#e6ebef','#bdcad4','#8ea1b1','#5e7689','#3d556a','#22344a'],
  rose:       ['#ece1de','#dbb9b9','#c08e95','#9a5e72','#6d3f56','#412236'],
  teal:       ['#dde7e5','#a8c2bf','#6fa097','#487a72','#2e5953','#1a3833'],
  lavender:   ['#e7e1ec','#c5b4d3','#a08abb','#7e639d','#5a417a','#3a2855'],
};

const series = context.panel.data.series && context.panel.data.series[0];
if (!series || !series.fields) return {};
const timeF = series.fields.find(f => f.type === 'time');
const valF  = series.fields.find(f => f.type === 'number');
if (!timeF || !valF) return {};

const len = (v) => (typeof v.length === 'number' ? v.length : (v.toArray ? v.toArray().length : 0));
const at  = (v, i) => (typeof v.get === 'function' ? v.get(i) : v[i]);

const lineColor = (PALETTES[context.grafana.replaceVariables('${palette}')] || PALETTES.slate)[2];

// Build points; pad closed-hour boundaries with 0 + null so each day
// renders as its own self-contained curve instead of being connected
// straight across overnight by ECharts.
const GAP_MS = 60 * 60 * 1000;   // any inter-point gap >1h ⇒ across-night break
const PAD_MS = 60 * 1000;        // synthetic boundary points 1 minute from neighbours
const points = [];
let prevT = null;
for (let i = 0; i < len(timeF.values); i++) {
  const t = at(timeF.values, i);
  const v = at(valF.values, i);
  if (prevT !== null && (t - prevT) > GAP_MS) {
    points.push([prevT + PAD_MS, 0]);    // drop to 0 right after last reading of the day
    points.push([prevT + PAD_MS + 1, null]);  // break line
    points.push([t - PAD_MS, 0]);        // start next day from 0
  }
  points.push([t, v]);
  prevT = t;
}

return {
  grid:    { left: 50, right: 20, top: 20, bottom: 30 },
  xAxis:   {
    type: 'time',
    axisLabel: {
      color: '#aaa',
      hideOverlap: true,
      formatter: (value) => {
        const d = new Date(value);
        const wd = new Intl.DateTimeFormat('en', { weekday: 'short', timeZone: 'Asia/Taipei' }).format(d);
        const tm = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Asia/Taipei' }).format(d);
        return wd + '\n' + tm;
      },
    },
  },
  yAxis:   { type: 'value', axisLabel: { color: '#aaa' }, name: '人', nameTextStyle: { color: '#aaa' } },
  tooltip: { trigger: 'axis', axisPointer: { type: 'cross', lineStyle: { color: 'rgba(255,255,255,0.3)' } }, formatter: (p) => p[0].axisValueLabel + '<br/>' + p[0].value[1] + ' 人' },
  series: [{
    type: 'line',
    data: points,
    connectNulls: false,
    showSymbol: false,
    symbol: 'circle',
    symbolSize: 8,
    lineStyle: { color: lineColor, width: 2 },
    itemStyle: { color: lineColor },
    areaStyle: { color: lineColor, opacity: 0.1 },
    emphasis: {
      itemStyle: { color: '#ffffff', borderColor: lineColor, borderWidth: 2 },
      scale: false,
    },
  }],
};
